import {
  DOCUMENTED_OPENAI_MODELS,
  GPT6_PRICING_TERMS,
} from "./model-context-catalog.js";

/** Only bounded, non-secret pricing labels may enter the durable usage ledger. */
export function projectUsagePricingContext(usage = {}) {
  const projected = {};
  for (const [key, alias] of [
    ["service_tier", "serviceTier"],
    ["regional_processing", "regionalProcessing"],
  ]) {
    if (!Object.hasOwn(usage, key) && !Object.hasOwn(usage, alias)) continue;
    if (
      Object.hasOwn(usage, key) &&
      Object.hasOwn(usage, alias) &&
      usage[key] !== usage[alias]
    ) {
      throw new TypeError(`usage pricing aliases conflict: ${key}`);
    }
    const value = Object.hasOwn(usage, key) ? usage[key] : usage[alias];
    if (key === "service_tier") {
      projected[key] =
        typeof value === "string" &&
        Object.hasOwn(GPT6_PRICING_TERMS.serviceMultipliers, value)
          ? value
          : "unknown";
    } else {
      if (typeof value !== "boolean")
        throw new TypeError("usage regional processing must be boolean");
      projected[key] = value;
    }
  }
  return projected;
}

/** Preserve per-request thresholds in a bounded set of aggregate price buckets. */
export function mergeUsagePricingBucket(entry, usage) {
  if (
    String(entry.provider).toLowerCase() !== "openai" ||
    !DOCUMENTED_OPENAI_MODELS[String(entry.model).toLowerCase()]?.pricing
  )
    return;
  const metadata = projectUsagePricingContext(usage);
  const promptTokens =
    usage.requestInputTokens ??
    usage.inputTokens +
      (usage.cacheReadTokens || 0) +
      (usage.cacheCreationTokens || 0);
  const long = promptTokens > GPT6_PRICING_TERMS.longContext.threshold;
  const serviceTier = metadata.service_tier || "standard";
  const regionalProcessing = metadata.regional_processing === true;
  entry.pricingBuckets ||= [];
  let bucket = entry.pricingBuckets.find(
    (item) =>
      item.serviceTier === serviceTier &&
      item.regionalProcessing === regionalProcessing &&
      item.requestInputTokens > GPT6_PRICING_TERMS.longContext.threshold ===
        long,
  );
  if (!bucket) {
    bucket = {
      inputTokens: 0,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheCreationTokens: 0,
      totalTokens: 0,
      calls: 0,
      serviceTier,
      regionalProcessing,
      requestInputTokens: promptTokens,
    };
    entry.pricingBuckets.push(bucket);
  }
  for (const key of [
    "inputTokens",
    "outputTokens",
    "cacheReadTokens",
    "cacheCreationTokens",
    "totalTokens",
    "calls",
  ]) {
    const value = usage[key] ?? (key === "calls" ? 1 : 0);
    if (
      !Number.isSafeInteger(value) ||
      value < 0 ||
      !Number.isSafeInteger(bucket[key] + value)
    ) {
      throw new TypeError(`invalid pricing bucket ${key}`);
    }
    bucket[key] += value;
  }
}

import { describe, it, expect, afterEach } from "vitest";
import {
  extractUsage,
  aggregateUsage,
  sessionUsage,
  allSessionsUsage,
  _deps,
} from "../../src/lib/session-usage.js";

const usageEvent = (model, input, output) => ({
  type: "token_usage",
  data: { model, usage: { input_tokens: input, output_tokens: output } },
});

describe("session-usage", () => {
  describe("extractUsage", () => {
    it("reads a token_usage event", () => {
      const u = extractUsage({
        type: "token_usage",
        timestamp: 1,
        data: {
          provider: "anthropic",
          model: "claude-opus-4-6",
          usage: { input_tokens: 100, output_tokens: 50 },
        },
      });
      expect(u).toEqual({
        provider: "anthropic",
        model: "claude-opus-4-6",
        inputTokens: 100,
        outputTokens: 50,
        totalTokens: 150,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        timestamp: 1,
      });
    });

    it("reads usage embedded in assistant_message", () => {
      const u = extractUsage({
        type: "assistant_message",
        timestamp: 2,
        data: {
          content: "...",
          usage: { prompt_tokens: 40, completion_tokens: 20, total_tokens: 60 },
          model: "gpt-4o",
        },
      });
      expect(u).toMatchObject({
        model: "gpt-4o",
        inputTokens: 40,
        outputTokens: 20,
        totalTokens: 60,
      });
    });

    it("returns null for events without usage", () => {
      expect(extractUsage({ type: "user_message", data: {} })).toBeNull();
      expect(
        extractUsage({ type: "assistant_message", data: { content: "hi" } }),
      ).toBeNull();
    });

    it("returns null for unknown event types", () => {
      expect(
        extractUsage({
          type: "tool_call",
          data: { usage: { input_tokens: 10 } },
        }),
      ).toBeNull();
    });

    it("returns null when all counts are zero", () => {
      expect(
        extractUsage({
          type: "token_usage",
          data: { usage: { input_tokens: 0, output_tokens: 0 } },
        }),
      ).toBeNull();
    });
  });

  describe("aggregateUsage", () => {
    it("rolls up total + per-model", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 100, output_tokens: 50 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 30, output_tokens: 10 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "openai",
            model: "gpt-4o",
            usage: { input_tokens: 20, output_tokens: 5 },
          },
        },
      ]);
      expect(agg.total).toEqual({
        inputTokens: 150,
        outputTokens: 65,
        totalTokens: 215,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        calls: 3,
      });
      expect(agg.byModel).toHaveLength(2);
      expect(agg.byModel[0]).toMatchObject({
        provider: "anthropic",
        model: "opus",
        inputTokens: 130,
        outputTokens: 60,
        calls: 2,
      });
      expect(agg.byModel[1]).toMatchObject({
        provider: "openai",
        model: "gpt-4o",
        inputTokens: 20,
        outputTokens: 5,
        calls: 1,
      });
    });

    it("ignores events without usage", () => {
      const agg = aggregateUsage([
        { type: "user_message", data: { content: "hi" } },
        { type: "tool_call", data: { tool: "read_file", args: {} } },
      ]);
      expect(agg.total.calls).toBe(0);
      expect(agg.byModel).toEqual([]);
    });

    it("handles empty + nullish input", () => {
      expect(aggregateUsage([]).total.calls).toBe(0);
      expect(aggregateUsage(null).total.calls).toBe(0);
    });

    it("sorts byModel descending by totalTokens", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            model: "small",
            usage: { input_tokens: 1, output_tokens: 1 },
          },
        },
        {
          type: "token_usage",
          data: {
            model: "big",
            usage: { input_tokens: 500, output_tokens: 500 },
          },
        },
      ]);
      expect(agg.byModel[0].model).toBe("big");
      expect(agg.byModel[1].model).toBe("small");
    });
  });

  describe("allSessionsUsage (resilient roll-up)", () => {
    const origReadEvents = _deps.readEvents;
    const origListSessions = _deps.listJsonlSessions;
    afterEach(() => {
      _deps.readEvents = origReadEvents;
      _deps.listJsonlSessions = origListSessions;
    });

    it("aggregates across sessions and skips one that fails to read", () => {
      _deps.listJsonlSessions = () => [
        { id: "good-1" },
        { id: "bad" },
        { id: "good-2" },
      ];
      _deps.readEvents = (id) => {
        if (id === "bad") {
          throw Object.assign(new Error("EACCES"), { code: "EACCES" });
        }
        return [usageEvent("opus", 100, 50)];
      };

      const r = allSessionsUsage();
      expect(r.skipped).toBe(1); // the unreadable session didn't abort the rest
      expect(r.sessions).toHaveLength(2); // good-1 + good-2
      expect(r.total.calls).toBe(2);
      expect(r.total.totalTokens).toBe(300); // 2 × (100+50)
      expect(r.byModel[0]).toMatchObject({ model: "opus", calls: 2 });
    });

    it("reports zero skipped when every session reads cleanly", () => {
      _deps.listJsonlSessions = () => [{ id: "a" }, { id: "b" }];
      _deps.readEvents = () => [usageEvent("gpt-4o", 10, 5)];
      const r = allSessionsUsage();
      expect(r.skipped).toBe(0);
      expect(r.sessions).toHaveLength(2);
    });

    it("sessionUsage rolls up a single session via the injected reader", () => {
      _deps.readEvents = () => [
        usageEvent("opus", 100, 50),
        usageEvent("opus", 30, 10),
      ];
      const r = sessionUsage("s1");
      expect(r.sessionId).toBe("s1");
      expect(r.total.calls).toBe(2);
      expect(r.total.inputTokens).toBe(130);
    });
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import Database from "better-sqlite3";
import { resolveModelCapabilityProfile } from "../../src/lib/model-capabilities.js";
import {
  estimateCost,
  lookupRate,
  mergePricing,
  priceRollup,
} from "../../src/lib/llm-pricing.js";
import {
  calculateCost,
  recordUsage,
  getUsageStats,
  getCostBreakdown,
} from "../../src/lib/token-tracker.js";
import {
  aggregateUsage,
  allSessionsUsage,
  _deps,
} from "../../src/lib/session-usage.js";
import { CostBudget } from "../../src/lib/cost-budget.js";
import { normalizeOpenAIResponsesResponse } from "../../src/lib/openai-responses.js";
import { projectRuntimeTokenUsage } from "../../src/lib/runtime-usage-ledger.js";
import { projectVerifiedSession } from "../../src/lib/causal-observability.js";
import { SessionResourceBudget } from "../../src/lib/session-resource-budget.js";

afterEach(() => vi.restoreAllMocks());

describe("September model release contracts", () => {
  it("preserves request pricing through durable projection, budget and Eval", () => {
    const records = [200000, 200000, 300000].map((input, index) =>
      projectRuntimeTokenUsage({
        provider: "openai",
        model: "gpt-6-sol",
        callId: `call-${index}`,
        usage: {
          input_tokens: input,
          output_tokens: 1000,
          service_tier: index === 1 ? "flex" : "fast",
          regional_processing: true,
        },
      }),
    );
    const events = [
      {
        type: "session_start",
        timestamp: 1,
        data: {
          observabilityScope: { workspaceId: "w", teamId: "t", policyId: "p" },
        },
      },
      ...records.map((data) => ({ type: "token_usage", data })),
    ];
    const budget = new CostBudget({ limitUsd: 100 });
