import { describe, expect, it } from "vitest";
import { aggregateUsage } from "../src/lib/session-usage.js";
import { estimateCost, priceRollup } from "../src/lib/llm-pricing.js";
import { GPT6_PRICING_TERMS } from "../src/lib/model-context-catalog.js";

const PROVIDER = "openai";
const MODEL = "gpt-6-sol";
const THRESHOLD = GPT6_PRICING_TERMS.longContext.threshold;

// Build a production-path token_usage event exactly as extractUsage consumes
// it (snake_case counts plus optional tier / regional flags).
function usageEvent({
  input_tokens = 0,
  output_tokens = 0,
  cache_read_input_tokens = 0,
  cache_creation_input_tokens = 0,
  service_tier,
  regional_processing,
} = {}) {
  const usage = {
    input_tokens,
    output_tokens,
    cache_read_input_tokens,
    cache_creation_input_tokens,
  };
  if (service_tier !== undefined) usage.service_tier = service_tier;
  if (regional_processing !== undefined) usage.regional_processing = regional_processing;
  return { type: "token_usage", timestamp: 1, data: { provider: PROVIDER, model: MODEL, usage } };
}

// Per-request contract reference computed through the same estimator the
// rollup boundary consumes, using the prompt tokens mergeUsagePricingBucket
// derives (input + cache read + cache creation) for the long-context decision.
function perRequestCost(raw) {
  const prompt =
    raw.input_tokens + raw.cache_read_input_tokens + raw.cache_creation_input_tokens;
  return estimateCost({
    provider: PROVIDER,
    model: MODEL,
    inputTokens: raw.input_tokens,
    outputTokens: raw.output_tokens,
    cacheReadTokens: raw.cache_read_input_tokens,
    cacheCreationTokens: raw.cache_creation_input_tokens,
    requestInputTokens: prompt,
    serviceTier: "standard",
  }).totalCost;
}

function rollupCost(events) {
  return priceRollup(aggregateUsage(events)).cost.totalCost;
}

describe("request-level caching and tiered long-context pricing", () => {
  it("partitions long-context crossing requests into separate buckets priced per request", () => {
    const longReq = { input_tokens: THRESHOLD + 1000, output_tokens: 1000 };
    const shortReq = { input_tokens: 100000, output_tokens: 1000 };
    const events = [usageEvent(longReq), usageEvent(shortReq)];
    expect(aggregateUsage(events).byModel[0].pricingBuckets).toHaveLength(2);
    const expected = perRequestCost(longReq) + perRequestCost(shortReq);
    expect(rollupCost(events)).toBeCloseTo(expected, 10);
  });

  it("prices the same total tokens with a different long/short distribution per request contract", () => {
    const longHeavy = [
      usageEvent({ input_tokens: THRESHOLD + 1000, output_tokens: 1000 }),
      usageEvent({ input_tokens: 100000, output_tokens: 1000 }),
    ];
    const allShort = [
      usageEvent({ input_tokens: 186500, output_tokens: 1000 }),
      usageEvent({ input_tokens: 186500, output_tokens: 1000 }),
    ];
    // Both sessions carry identical aggregate tokens (373000 prompt + 2000 out).
    const expectedHeavy = longHeavy.reduce((s, e) => s + perRequestCost(e.data.usage), 0);
    const expectedShort = allShort.reduce((s, e) => s + perRequestCost(e.data.usage), 0);
    expect(rollupCost(longHeavy)).toBeCloseTo(expectedHeavy, 10);
    expect(rollupCost(allShort)).toBeCloseTo(expectedShort, 10);
    // The one request that crossed the long-context threshold bills at the
    // 2x input multiplier, so the long-heavy distribution must cost more.
    expect(rollupCost(longHeavy)).toBeGreaterThan(rollupCost(allShort));
  });

  it("bills cache-read tokens at their own rate inside the multiplier bucket their request landed in", () => {
    // Same aggregate totals (input 273000, cacheRead 1000, output 2000), but the
    // cache tokens ride on the long request vs on the short request.
    const cacheOnLong = [
      usageEvent({ input_tokens: 272000, cache_read_input_tokens: 1000, output_tokens: 1000 }),
      usageEvent({ input_tokens: 1000, output_tokens: 1000 }),
    ];
    const cacheOnShort = [
      usageEvent({ input_tokens: 273000, output_tokens: 1000 }),
      usageEvent({ cache_read_input_tokens: 1000, output_tokens: 1000 }),
    ];
    const expectedLong = cacheOnLong.reduce((s, e) => s + perRequestCost(e.data.usage), 0);
    const expectedShort = cacheOnShort.reduce((s, e) => s + perRequestCost(e.data.usage), 0);
    expect(rollupCost(cacheOnLong)).toBeCloseTo(expectedLong, 10);
    expect(rollupCost(cacheOnShort)).toBeCloseTo(expectedShort, 10);
    // Identical totals, different cache placement -> different per-request bill.
    expect(rollupCost(cacheOnLong)).not.toBeCloseTo(rollupCost(cacheOnShort), 10);
  });

  it("keeps cache tokens as a distinct component within a shared long-context bucket", () => {
    const events = [
      usageEvent({ input_tokens: 200000, cache_read_input_tokens: 73000, output_tokens: 1000 }),
      usageEvent({ input_tokens: 273000, output_tokens: 1000 }),
    ];
    const model = aggregateUsage(events).byModel[0];
    expect(model.pricingBuckets).toHaveLength(1);
    const bucket = model.pricingBuckets[0];
    expect(bucket.inputTokens).toBe(473000);
    expect(bucket.cacheReadTokens).toBe(73000);
    const expected = events.reduce((s, e) => s + perRequestCost(e.data.usage), 0);
    expect(rollupCost(events)).toBeCloseTo(expected, 10);
  });

  it("treats the long-context threshold boundary exactly per request", () => {
    const atThreshold = usageEvent({ input_tokens: THRESHOLD, output_tokens: 1000 });
    const justAbove = usageEvent({ input_tokens: THRESHOLD + 1, output_tokens: 1000 });
    const events = [atThreshold, justAbove];
    expect(aggregateUsage(events).byModel[0].pricingBuckets).toHaveLength(2);
    const expected =
      perRequestCost(atThreshold.data.usage) + perRequestCost(justAbove.data.usage);
    expect(rollupCost(events)).toBeCloseTo(expected, 10);
  });

  it("rolls calls and token totals per request while honoring per-request tier contracts", () => {
    const events = [
      usageEvent({ input_tokens: 273000, output_tokens: 1000, service_tier: "fast" }),
      usageEvent({ input_tokens: 100000, output_tokens: 1000 }),
    ];
    const agg = aggregateUsage(events);
    expect(agg.total.inputTokens).toBe(373000);
    expect(agg.total.outputTokens).toBe(2000);
    expect(agg.total.calls).toBe(2);
    expect(agg.byModel[0].pricingBuckets).toHaveLength(2);
    const fastBucketCost = estimateCost({
      provider: PROVIDER,
      model: MODEL,
      inputTokens: 273000,
      outputTokens: 1000,
      requestInputTokens: 273000,
      serviceTier: "fast",
    }).totalCost;
    const standardBucketCost = perRequestCost({ input_tokens: 100000, output_tokens: 1000 });
    expect(rollupCost(events)).toBeCloseTo(fastBucketCost + standardBucketCost, 10);
  });
});

